<template><div class="app-container"><h2 style="color:#456747">用户与反馈</h2><p style="color:#929d87">总后台统一处理用户服务，商家账号无法访问此页面的数据。</p><el-tabs v-model="tab"><el-tab-pane label="用户列表" name="members"><el-table :data="members"><el-table-column label="编号" prop="id"/><el-table-column label="昵称" prop="nickname"/><el-table-column label="积分" prop="points"/><el-table-column label="注册时间" prop="created_at"/></el-table><p>显示最近500位用户</p></el-tab-pane><el-tab-pane label="意见反馈" name="feedback"><el-table :data="feedback"><el-table-column label="编号" prop="id" width="80"/><el-table-column label="用户" prop="member_id" width="80"/><el-table-column label="反馈内容" prop="content" min-width="250"/><el-table-column label="回复" prop="reply" min-width="250"/><el-table-column label="提交时间" prop="created_at" width="170"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="reply(row)">回复</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></div></template>
<script setup>import {ref,onMounted} from 'vue';import {ElMessageBox,ElMessage} from 'element-plus';import {foodGet,foodPost} from '@/api/food';const members=ref([]),feedback=ref([]),tab=ref('members');async function load(){const [m,f]=await Promise.all([foodGet('/members'),foodGet('/feedback')]);members.value=m.data;feedback.value=f.data}async function reply(row){const {value}=await ElMessageBox.prompt('请输入客服回复','回复反馈',{inputType:'textarea',inputValue:row.reply||'',inputValidator:v=>!!v?.trim()||'请填写回复'});await foodPost('/feedback/'+row.id,{reply:value});ElMessage.success('回复已发送到用户消息中心');load()}onMounted(load)</script>
